const AI_CONFIG_VERSION = "2026-03-v2";
const fetchWithTimeout = (url, opts, ms = 40000) => {
  const ctrl = new AbortController();
  const id = setTimeout(() => ctrl.abort(), ms);
  return fetch(url, { ...opts, signal: ctrl.signal }).finally(() =>
    clearTimeout(id)
  );
};
