  const escapeCtrl = (s) => {
    const out = [];
    let inStr = false;
    let esc = false;
    for (let ix = 0; ix < s.length; ix++) {
      const ch = s[ix];
      const code = ch.charCodeAt(0);
      if (esc) {
        out.push(ch);
        esc = false;
        continue;
      }
      if (code === 92) {
        out.push(ch);
        esc = true;
        continue;
      }
      if (code === 34) {
        out.push(ch);
        inStr = !inStr;
        continue;
      }
      if (inStr && code === 10) {
        out.push("\\n");
        continue;
      }
      if (inStr && code === 13) {
        continue;
      }
      if (inStr && code === 9) {
        out.push("\\t");
        continue;
      }
      if (inStr && code < 32) {
        out.push(" ");
        continue;
      }
      out.push(ch);
    }
    return out.join("");
  };
  let repaired = escapeCtrl(clean);
  try {
    return JSON.parse(repaired);
  } catch (_) {}
  repaired = repaired
    .replace(/,\s*([}\]])/g, "$1")
    .replace(/([{,]\s*)'([^']+)'\s*:/g, '$1"$2":');
  try {
    return JSON.parse(repaired);
  } catch (_) {}
  let fixed = repaired
    .replace(/,?\s*"[^"]*":\s*"[^"]*$/, "")
    .replace(/,?\s*"[^"]*":\s*\[[^\]]*$/, "")
    .replace(/,?\s*"[^"]*$/, "");
  const opens =
    (fixed.match(/{/g) || []).length - (fixed.match(/}/g) || []).length;
  const arrOpens =
    (fixed.match(/\[/g) || []).length - (fixed.match(/\]/g) || []).length;
  fixed += "]".repeat(Math.max(0, arrOpens)) + "}".repeat(Math.max(0, opens));
  try {
    return JSON.parse(fixed);
  } catch (_) {}
  const result = {};
  const fieldRe = /"(\w+)"\s*:\s*"((?:[^"\\]|\\.)*)"/g;
  let fm;
  while ((fm = fieldRe.exec(repaired)) !== null)
    result[fm[1]] = fm[2].replace(/\\n/g, "\n");
