  // B-17: TELEMEDICINA - Jitsi Meet (Res. 2654/2019)
  // Videoconsulta integrada con consentimiento digital, sin costo por minuto
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  const renderTelemedicina = () => {
    // â”€â”€ SECRETARIA GATE: "Telemedicina" requiere autorización del admin â”€â”€
    if (
      currentUser?.role === "secretaria" &&
      !_secretariaPuede("telemedicina", currentUser, usersList)
    )
      return (
        <div className="min-h-screen bg-gray-50 font-sans">
          {renderNavbar()}
          <div className="max-w-xl mx-auto px-4 py-16 text-center">
            <div className="bg-amber-50 border-2 border-amber-300 rounded-2xl p-8 space-y-3">
              <div className="text-5xl">ðŸ”</div>
              <p className="font-black text-amber-800 text-xl">
                Módulo restringido
              </p>
              <p className="text-amber-700 text-sm font-bold">Telemedicina</p>
              <p className="text-amber-600 text-xs leading-relaxed">
                Este módulo requiere autorización explícita del administrador.
                <br />
                Solicita que habilite el permiso <strong>
                  "Telemedicina"
                </strong>{" "}
                en tu perfil.
                <br />
                (Usuarios â†’ tu nombre â†’ ðŸ” Permisos de secretaria)
              </p>
              <button
                onClick={() => goBack()}
                className="mt-3 bg-amber-600 text-white px-5 py-2 rounded-lg text-sm font-bold hover:bg-amber-700 transition"
              >
                â† Volver al panel
              </button>
            </div>
          </div>
        </div>
      );
    const _genRoomName = (doc, fecha, hora) => {
      const ts = `${doc}-${fecha}-${hora}`.replace(/[^a-zA-Z0-9]/g, "");
      return `SISOOcupaSalud-${ts}`;
    };
    const _syncTele = (lista) => {
      setTeleconsultas(lista);
      _ls.setItem("siso_teleconsultas", JSON.stringify(lista));
      _sbSet(`siso_teleconsultas_${currentUser?.user || "shared"}`, lista);
    };

    const handleIniciarSala = () => {
      if (!teleForm.paciente.trim()) {
        showAlert("âš ï¸ Ingrese el nombre del paciente.");
        return;
      }
      if (!teleForm.documento.trim()) {
        showAlert("âš ï¸ Ingrese el número de documento del paciente.");
        return;
      }
      if (!teleForm.hora.trim()) {
        showAlert("âš ï¸ Ingrese la hora de la teleconsulta.");
        return;
      }
      if (!teleForm.consentimientoTele) {
        showAlert(
          "âš ï¸ El paciente debe aceptar el consentimiento de telemedicina."
        );
        return;
      }
      const roomName = _genRoomName(
        teleForm.documento,
        teleForm.fecha,
        teleForm.hora
      );
      const nuevaTele = {
        id: "tele_" + Date.now(),
        roomName,
        paciente: teleForm.paciente,
        documento: teleForm.documento,
        celular: teleForm.celular,
        fecha: teleForm.fecha,
        hora: teleForm.hora,
        motivo: teleForm.motivo,
        notas: teleForm.notas,
        consentimientoTele: true,
        consentimientoTs: new Date().toISOString(),
        medico: currentUser?.name || currentUser?.user,
        estado: "esperando",
        horaInicio: null,
        horaFin: null,
      };
      const lista = [nuevaTele, ...teleconsultas];
      _syncTele(lista);
      // Agregar a sala de espera
      setTeleEspera(function (prev) { return prev.concat([{ id: nuevaTele.id, paciente: nuevaTele.paciente, documento: nuevaTele.documento, hora: nuevaTele.hora, roomName: roomName }]); });
      setTeleSalaActiva({
        roomName,
        paciente: teleForm.paciente,
        documento: teleForm.documento,
        celular: teleForm.celular,
        fecha: teleForm.fecha,
        hora: teleForm.hora,
      });
    };

    const handleCerrarSala = () => {
      if (teleSalaActiva) {
        var horaFinTele = new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit", hour12: false }).replace(".", ":");
        const lista = teleconsultas.map(function (t) {
          if (t.roomName === teleSalaActiva.roomName) {
            return Object.assign({}, t, { estado: "completada", finTs: new Date().toISOString(), horaFin: horaFinTele });
          }
          return t;
        });
        _syncTele(lista);
        // Remover de sala de espera
        setTeleEspera(function (prev) { return prev.filter(function (e) { return e.roomName !== teleSalaActiva.roomName; }); });
      }
      setTeleSalaActiva(null);
    };
    // Iniciar consulta (cambiar de esperando a en_consulta)
    const handleIniciarConsulta = (teleId) => {
      var horaInicioTele = new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit", hour12: false }).replace(".", ":");
      const lista = teleconsultas.map(function (t) {
        if (t.id === teleId) {
          return Object.assign({}, t, { estado: "activa", horaInicio: horaInicioTele });
        }
        return t;
      });
      _syncTele(lista);
      var found = teleconsultas.find(function (t) { return t.id === teleId; });
      if (found) {
        setTeleSalaActiva({
          roomName: found.roomName,
          paciente: found.paciente,
          documento: found.documento,
          celular: found.celular || "",
          fecha: found.fecha,
          hora: found.hora,
        });
      }
      // Remover de espera visual
      setTeleEspera(function (prev) { return prev.filter(function (e) { return e.id !== teleId; }); });
    };
    // Crear HC desde teleconsulta finalizada
    const crearHCDesdeTele = (tele) => {
      var newId = "pac_" + Date.now();
      setData(Object.assign({}, initialGeneralPatientState, {
        id: newId,
        _medicoId: currentUser?.user,
        nombres: tele.paciente,
        docNumero: tele.documento,
        celular: tele.celular || "",
        motivoConsulta: "Teleconsulta \u2014 " + (tele.motivo || "Sin motivo registrado"),
        _teleId: tele.id,
      }));
      setDataType("general");
      setActiveTab("formGeneral");
      setView("historia");
    };

    const jitsiUrl = teleSalaActiva
      ? `https://meet.jit.si/${
          teleSalaActiva.roomName
        }#userInfo.displayName="${encodeURIComponent(
          currentUser?.name || "Dr. Cucalón"
        )}"&config.startWithVideoMuted=false&config.prejoinPageEnabled=false`
      : null;

    return (
      <div className="min-h-screen bg-gray-50 font-sans">
        {renderNavbar()}
        <div className="p-4 max-w-5xl mx-auto space-y-4">
          {/* Header */}
          <div className="bg-gradient-to-r from-blue-700 to-indigo-700 rounded-2xl p-5 text-white">
            <div className="flex items-center justify-between flex-wrap gap-3">
              <div className="flex items-center gap-3">
                <button
                  onClick={() => goBack()}
                  className="bg-white/20 hover:bg-white/30 text-white px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 flex-shrink-0"
                >
                  â† Volver
                </button>
                <div>
                  <h2 className="text-lg font-black">
                    ðŸ©º Telemedicina Ocupacional
                  </h2>
                  <p className="text-blue-200 text-xs mt-0.5">
                    Res. 2654/2019 · Jitsi Meet · Sin costo por videollamada
                  </p>
                </div>
              </div>
              <div className="flex gap-2 items-center">
                {teleconsultas.filter(function (t) { return t.estado === "esperando"; }).length > 0 && (
                  <span className="bg-red-500 text-white text-[10px] font-black px-2 py-1 rounded-full animate-pulse">
                    {"ðŸ”´ " + teleconsultas.filter(function (t) { return t.estado === "esperando"; }).length + " en espera"}
                  </span>
                )}
                <button
                  onClick={() => setTeleTab("nueva")}
                  className={`px-3 py-1.5 text-xs font-bold rounded-lg ${
                    teleTab === "nueva"
                      ? "bg-white text-blue-700"
                      : "bg-blue-800 text-blue-200 hover:bg-blue-600"
                  }`}
                >
                  {"âž• Nueva consulta"}
                </button>
                <button
                  onClick={() => setTeleTab("historial")}
                  className={`px-3 py-1.5 text-xs font-bold rounded-lg ${
                    teleTab === "historial"
                      ? "bg-white text-blue-700"
                      : "bg-blue-800 text-blue-200 hover:bg-blue-600"
                  }`}
                >
                  ðŸ“‹ Historial ({teleconsultas.length})
                </button>
              </div>
            </div>
          </div>

          {/* Sala activa - Jitsi iframe */}
          {teleSalaActiva && (
            <div className="bg-white rounded-2xl shadow-lg overflow-hidden border-2 border-blue-500">
              <div className="bg-blue-600 px-4 py-2 flex items-center justify-between">
                <div className="text-white text-xs font-bold flex items-center gap-2">
                  {"ðŸ”´ CONSULTA EN CURSO - " + teleSalaActiva.paciente + " · " + teleSalaActiva.fecha + " " + teleSalaActiva.hora}
                  {teleEspera.length > 0 && (
                    <span className="bg-red-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full animate-pulse">
                      {"ðŸ”´ " + teleEspera.length + " paciente" + (teleEspera.length !== 1 ? "s" : "") + " esperando"}
                    </span>
                  )}
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={handleCerrarSala}
                    className="bg-red-500 hover:bg-red-600 text-white text-xs font-black px-3 py-1 rounded-lg"
                  >
                    â¹ Finalizar consulta
                  </button>
                </div>
              </div>
              <div className="bg-gray-50 flex flex-col items-center justify-center gap-5 py-12">
                <div className="text-center">
                  <div className="text-5xl mb-3">ðŸŽ¥</div>
                  <p className="font-black text-gray-800 text-base">
                    Sala lista para iniciar
                  </p>
                  <p className="text-xs text-gray-500 mt-1">
                    La videollamada se abre en una nueva pestaña del navegador
                  </p>
                </div>
                <div className="flex flex-col items-center gap-3 w-full max-w-xs">
                  <a
                    href={jitsiUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-3 px-6 rounded-xl text-sm text-center flex items-center justify-center gap-2 shadow-lg"
                  >
                    ðŸŽ¥ Abrir videollamada
                  </a>
                  <button
                    onClick={() => {
                      navigator.clipboard?.writeText(jitsiUrl);
                      showAlert(
                        "ðŸ”— Enlace copiado al portapapeles. Envíelo al paciente."
                      );
                    }}
                    className="w-full bg-white border border-blue-200 text-blue-700 font-bold py-2 px-4 rounded-xl text-xs flex items-center justify-center gap-2"
                  >
                    ðŸ“‹ Copiar enlace para el paciente
                  </button>
                  {teleSalaActiva.celular && (
                    <a
                      href={"https://wa.me/" + (teleSalaActiva.celular || "").replace(/\D/g, "") + "?text=" + encodeURIComponent("Hola " + teleSalaActiva.paciente + ", su teleconsulta esta lista. Ingrese al siguiente enlace: " + jitsiUrl)}
                      target="_blank"
                      rel="noreferrer"
                      className="w-full flex items-center justify-center gap-2 bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-xl text-sm font-bold transition"
                    >
                      {"ðŸ“± Enviar enlace por WhatsApp"}
                    </a>
                  )}
                  {!teleSalaActiva.celular && (
                    <p className="text-[10px] text-amber-600 text-center font-bold">
                      {"âš ï¸ Sin celular registrado - No se puede enviar por WhatsApp"}
                    </p>
                  )}
                  <p className="text-[10px] text-gray-400 text-center">
                    {"Enlace \u00FAnico: " + jitsiUrl}
                  </p>
                </div>
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-[10px] text-blue-700 max-w-sm">
                  <p className="font-black">â„¹ï¸ Cómo funciona</p>
                  <p className="mt-0.5">
                    1. Presione "Abrir videollamada" - se abre en nueva pestaña
                  </p>
                  <p>
                    2. Comparta el enlace con el paciente por WhatsApp o Email
                  </p>
                  <p>
                    3. Ambos entran al mismo enlace y la sala es privada y
                    cifrada
                  </p>
                </div>
              </div>
              <div className="px-4 py-2 bg-blue-50 text-[10px] text-blue-700 font-bold">
                ðŸ”’ Sala privada: {teleSalaActiva.roomName} · La videollamada
                ocurre en servidores de Jitsi Meet (meet.jit.si) · Ningún dato
                clínico se transmite al proveedor de video
              </div>
            </div>
          )}

          {/* Formulario nueva consulta */}
          {teleTab === "nueva" && !teleSalaActiva && (
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-5 space-y-4">
              <h3 className="text-sm font-black text-gray-800">
                Datos de la teleconsulta
              </h3>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-bold text-gray-600 mb-1 uppercase">
                    Nombre del paciente *
                  </label>
                  <input
                    value={teleForm.paciente}
                    onChange={(e) =>
                      setTeleForm((p) => ({ ...p, paciente: e.target.value }))
                    }
                    className="w-full p-2 border rounded-lg text-sm"
                    placeholder="Nombre completo"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-600 mb-1 uppercase">
                    Documento de identidad *
                  </label>
                  <input
                    value={teleForm.documento}
                    onChange={(e) =>
                      setTeleForm((p) => ({ ...p, documento: e.target.value }))
                    }
                    className="w-full p-2 border rounded-lg text-sm"
                    placeholder="CC / CE / PP"
                  />
                </div>
                <div className="col-span-2">
                  <label className="block text-[10px] font-bold text-gray-600 mb-1 uppercase">
                    {"ðŸ“± Celular del paciente (WhatsApp)"}
                  </label>
                  <input
                    value={teleForm.celular}
                    onChange={(e) =>
                      setTeleForm((p) => ({ ...p, celular: e.target.value }))
                    }
                    className="w-full p-2 border rounded-lg text-sm"
                    placeholder="Ej: +573001234567"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-600 mb-1 uppercase">
                    Fecha *
                  </label>
                  <input
                    type="date"
                    value={teleForm.fecha}
                    onChange={(e) =>
                      setTeleForm((p) => ({ ...p, fecha: e.target.value }))
                    }
                    className="w-full p-2 border rounded-lg text-sm"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-600 mb-1 uppercase">
                    Hora *
                  </label>
                  <input
                    type="time"
                    value={teleForm.hora}
                    onChange={(e) =>
                      setTeleForm((p) => ({ ...p, hora: e.target.value }))
                    }
                    className="w-full p-2 border rounded-lg text-sm"
                  />
                </div>
                <div className="col-span-2">
                  <label className="block text-[10px] font-bold text-gray-600 mb-1 uppercase">
                    Motivo de consulta
                  </label>
                  <input
                    value={teleForm.motivo}
                    onChange={(e) =>
                      setTeleForm((p) => ({ ...p, motivo: e.target.value }))
                    }
                    className="w-full p-2 border rounded-lg text-sm"
                    placeholder="Ej: Evaluación periódica, seguimiento recomendación..."
                  />
                </div>
              </div>

              {/* Consentimiento telemedicina */}
              <div
                className={`p-4 rounded-xl border-2 ${
                  teleForm.consentimientoTele
                    ? "bg-emerald-50 border-emerald-400"
                    : "bg-amber-50 border-amber-300"
                }`}
              >
                <p className="text-xs font-black text-gray-800 mb-2">
                  Consentimiento Informado para Telemedicina (Res. 2654/2019)
                </p>
                <div className="text-[11px] text-gray-600 space-y-1 mb-3">
                  <p>
                    • La consulta se realizará por videollamada a través de
                    Jitsi Meet, una plataforma de comunicación cifrada.
                  </p>
                  <p>
                    • El médico puede tomar notas clínicas durante la sesión,
                    las cuales formarán parte de la Historia Clínica.
                  </p>
                  <p>
                    • Esta modalidad no reemplaza la evaluación física cuando la
                    condición clínica lo requiera.
                  </p>
                  <p>
                    • Tiene derecho a interrumpir la consulta en cualquier
                    momento sin afectar su atención posterior.
                  </p>
                </div>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={teleForm.consentimientoTele}
                    onChange={(e) =>
                      setTeleForm((p) => ({
                        ...p,
                        consentimientoTele: e.target.checked,
                      }))
                    }
                    className="w-4 h-4 accent-emerald-600"
                  />
                  <span className="text-xs font-bold text-gray-700">
                    El paciente <strong>{teleForm.paciente || "---"}</strong> ha
                    leído y aceptado este consentimiento de telemedicina
                  </span>
                </label>
              </div>

              <button
                onClick={handleIniciarSala}
                disabled={
                  !teleForm.paciente ||
                  !teleForm.documento ||
                  !teleForm.hora ||
                  !teleForm.consentimientoTele
                }
                className="w-full py-3 bg-blue-600 hover:bg-blue-700 disabled:opacity-40 disabled:cursor-not-allowed text-white font-black rounded-xl flex items-center justify-center gap-2"
              >
                ðŸŽ¥ Iniciar videoconsulta
              </button>
            </div>
          )}

          {/* Sala de espera telemedicina */}
          {teleEspera.length > 0 && !teleSalaActiva && (
            <div className="bg-white rounded-2xl shadow-sm border-2 border-amber-300 overflow-hidden">
              <div className="bg-amber-50 px-4 py-3 border-b border-amber-200">
                <p className="text-sm font-black text-amber-800">
                  {"ðŸ”´ Sala de Espera (" + teleEspera.length + " paciente" + (teleEspera.length !== 1 ? "s" : "") + ")"}
                </p>
              </div>
              <div className="divide-y divide-gray-100">
                {teleconsultas.filter(function (t) { return t.estado === "esperando"; }).map(function (t) {
                  return (
                    <div key={t.id} className="flex items-center justify-between p-4 hover:bg-amber-50">
                      <div>
                        <p className="text-xs font-bold text-gray-800">
                          {t.paciente + " · " + t.documento}
                        </p>
                        <p className="text-[10px] text-gray-500 mt-0.5">
                          {"ðŸ“… " + t.fecha + " " + t.hora + " · " + (t.motivo || "Sin motivo")}
                        </p>
                      </div>
                      <button
                        onClick={function () { handleIniciarConsulta(t.id); }}
                        className="bg-blue-600 hover:bg-blue-700 text-white text-xs font-black px-4 py-2 rounded-xl"
                      >
                        {"â–¶ Iniciar consulta"}
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Historial de teleconsultas */}
          {teleTab === "historial" && (
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="px-4 py-3 border-b border-gray-100 bg-indigo-50">
                <p className="text-sm font-black text-indigo-800">
                  Historial de Teleconsultas
                </p>
              </div>
              {teleconsultas.length === 0 ? (
                <div className="text-center py-12 text-gray-400">
                  <p className="text-3xl mb-2">{"ðŸ“¹"}</p>
                  <p className="text-sm font-bold">
                    Sin teleconsultas registradas
                  </p>
                </div>
              ) : (
                <div className="divide-y divide-gray-100">
                  {teleconsultas.map(function (t) {
                    var estadoLabel = t.estado === "activa" ? "ðŸ”µ En curso" : t.estado === "esperando" ? "ðŸŸ¡ Programada" : "âœ… Finalizada";
                    var estadoClass = t.estado === "activa" ? "bg-blue-100 text-blue-700" : t.estado === "esperando" ? "bg-yellow-100 text-yellow-700" : "bg-emerald-100 text-emerald-700";
                    var duracionStr = "";
                    if (t.horaInicio && t.horaFin) {
                      var partsI = t.horaInicio.split(":");
                      var partsF = t.horaFin.split(":");
                      if (partsI.length === 2 && partsF.length === 2) {
                        var minI = parseInt(partsI[0], 10) * 60 + parseInt(partsI[1], 10);
                        var minF = parseInt(partsF[0], 10) * 60 + parseInt(partsF[1], 10);
                        var diff = minF - minI;
                        if (diff > 0) duracionStr = diff + " min";
                      }
                    }
                    return (
                      <div key={t.id} className="flex items-center justify-between p-4 hover:bg-gray-50">
                        <div>
                          <p className="text-xs font-bold text-gray-800">
                            {t.paciente + " "}
                            <span className="font-normal text-gray-400">
                              {" · " + t.documento}
                            </span>
                          </p>
                          <p className="text-[10px] text-gray-500 mt-0.5">
                            {"ðŸ“… " + t.fecha + " " + t.hora + " · " + (t.motivo || "Sin motivo registrado")}
                          </p>
                          <div className="flex items-center gap-2 mt-0.5">
                            <p className="text-[10px] text-gray-400">
                              {"ðŸ‘¤ " + t.medico}
                            </p>
                            {duracionStr && (
                              <p className="text-[10px] text-blue-600 font-bold">
                                {"â± Duración: " + duracionStr}
                              </p>
                            )}
                            {t.horaInicio && (
                              <p className="text-[10px] text-gray-400">
                                {"ðŸ• " + t.horaInicio + (t.horaFin ? " â†’ " + t.horaFin : "")}
                              </p>
                            )}
                          </div>
                        </div>
                        <div className="flex flex-col items-end gap-1.5">
                          <span className={"text-[10px] font-black px-2 py-1 rounded-full " + estadoClass}>
                            {estadoLabel}
                          </span>
                          {t.estado === "completada" && (
                            <button
                              onClick={function () { crearHCDesdeTele(t); }}
                              className="text-[10px] font-bold text-indigo-600 hover:text-indigo-800 bg-indigo-50 hover:bg-indigo-100 px-2 py-1 rounded-lg transition"
                            >
                              {"ðŸ“‹ Crear HC de esta teleconsulta"}
                            </button>
                          )}
                          {t.estado === "esperando" && (
                            <button
                              onClick={function () { handleIniciarConsulta(t.id); }}
                              className="text-[10px] font-bold text-blue-600 hover:text-blue-800 bg-blue-50 hover:bg-blue-100 px-2 py-1 rounded-lg transition"
                            >
                              {"â–¶ Iniciar consulta"}
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {/* Nota normativa */}
          <div className="bg-blue-50 border border-blue-200 rounded-xl p-4">
            <p className="text-[10px] font-black text-blue-800 mb-1">
              ðŸ“‹ Marco normativo: Res. 2654 de 2019
            </p>
            <p className="text-[10px] text-blue-700">
              La telemedicina en Colombia está regulada por la Resolución 2654
              de 2019. Para prestar este servicio como IPS habilitada se
              requiere: (1) inscribir la modalidad en el REPS, (2) tener
              consentimiento informado firmado por el paciente, (3) garantizar
              la confidencialidad de la comunicación, y (4) registrar la
              atención en la HC. Jitsi Meet utiliza cifrado end-to-end
              (SRTP/DTLS). Ningún dato clínico se almacena en sus servidores.
            </p>
          </div>
        </div>
      </div>
    );
  };

  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  // B-16: ADJUNTOS DE PARACLÍNICOS - Supabase Storage
  // Res. 1843/2025 Art.12 - Espirometría, Audiometría, RX, Laboratorios
  // â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
  const renderTabAdjuntos = () => {
    const TIPOS_ADJUNTO = [
      { valor: "espirometria", etiqueta: "ðŸ« Espirometría" },
      { valor: "audiometria", etiqueta: "ðŸ‘‚ Audiometría" },
      { valor: "rayos_x", etiqueta: "ðŸ©» Rayos X / Imágenes" },
      { valor: "laboratorio", etiqueta: "ðŸ§ª Laboratorio" },
      { valor: "optometria", etiqueta: "ðŸ‘ Optometría" },
      { valor: "ecg", etiqueta: "â¤ï¸ ECG / Holter" },
      { valor: "vacunacion", etiqueta: "ðŸ’‰ Carnet Vacunación" },
      { valor: "otro", etiqueta: "ðŸ“„ Otro documento" },
    ];
    const adjuntos = data.adjuntos || [];
    const MAX_MB = 10;
    const MAX_BYTES = MAX_MB * 1024 * 1024;
    const TIPOS_MIME = [
      "application/pdf",
      "image/png",
      "image/jpeg",
      "image/tiff",
      "image/webp",
    ];

    const handleSubirAdjunto = async (e) => {
      const file = e.target.files?.[0];
      if (!file) return;
      if (!TIPOS_MIME.includes(file.type)) {
        showAlert("âš ï¸ Solo se permiten PDF, PNG, JPG, TIFF o WebP.");
        return;
      }
      if (file.size > MAX_BYTES) {
        showAlert(`âš ï¸ El archivo supera el límite de ${MAX_MB} MB.`);
        return;
      }

      const tipoSelect = document.getElementById("adjunto-tipo-select");
      const tipoVal = tipoSelect ? tipoSelect.value : "otro";
      const tipoLabel =
        TIPOS_ADJUNTO.find((t) => t.valor === tipoVal)?.etiqueta || "Documento";

      const ts = Date.now();
      const ext = file.name.split(".").pop().toLowerCase();
      const userId = currentUser?.user || "unknown";
      const hcId = data.id || "hc_" + ts;
      const storagePath = `${userId}/${hcId}/${ts}-${tipoVal}.${ext}`;
      const nombreVisible = `${tipoLabel.replace(/[^\w\s]/g, "").trim()} - ${
        file.name
      }`;

      showAlert("â³ Subiendo archivo a Supabase Storage...");

      const result = await _sbStorageUpload(storagePath, file);
      if (!result.ok) {
        showAlert(
          `âŒ Error al subir: ${
            result.error ||
            "Verifica que el bucket siso-adjuntos esté habilitado en Supabase."
          }`
        );
        return;
      }

      const nuevoAdj = {
        id: `adj_${ts}`,
        nombre: nombreVisible,
        tipo: tipoVal,
        tipoLabel,
        mimeType: file.type,
        tamano: file.size,
        fecha: new Date().toISOString(),
        subidoPor: userId,
        path: storagePath,
      };

      const nuevosAdjuntos = [...adjuntos, nuevoAdj];
      setData((prev) => ({ ...prev, adjuntos: nuevosAdjuntos }));
      showAlert(`âœ… "${file.name}" subido correctamente como ${tipoLabel}.`);
      if (tipoSelect) tipoSelect.value = "otro";
      e.target.value = "";
    };

    const handleVerAdjunto = async (adj) => {
      const url = await _sbStorageGetSignedUrl(adj.path);
      if (url) {
        window.open(url, "_blank");
      } else {
        showAlert(
          "âš ï¸ No se pudo obtener el enlace. Verifica la conexión con Supabase."
        );
      }
    };

    const handleEliminarAdjunto = async (adj) => {
      if (data.estadoHistoria === "Cerrada") {
        showAlert("â„¹ï¸ No se pueden eliminar adjuntos de una HC cerrada.");
        return;
      }
      const ok = await new Promise((res) =>
        setConfirmConfig({
          msg: `¿Eliminar "${adj.nombre}"? Esta acción no se puede deshacer.`,
          onConfirm: () => res(true),
          onCancel: () => res(false),
        })
      );
      if (!ok) return;
      await _sbStorageDelete(adj.path);
      const filtrados = adjuntos.filter((a) => a.id !== adj.id);
      setData((prev) => ({ ...prev, adjuntos: filtrados }));
      showAlert("ðŸ—‘ Adjunto eliminado.");
    };

    const formatBytes = (b) =>
      b < 1024 * 1024
        ? `${(b / 1024).toFixed(1)} KB`
        : `${(b / 1024 / 1024).toFixed(2)} MB`;

    return (
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        {/* Header */}
        <div className="flex items-center gap-2 px-4 py-3 border-b border-gray-100 bg-teal-50">
          <span className="text-sm font-black text-teal-800">
            ðŸ“Ž Adjuntos de Paraclínicos
          </span>
          <span className="text-[10px] text-teal-600 bg-teal-100 px-2 py-0.5 rounded-full">
            Res. 1843/2025 · Supabase Storage
          </span>
          <span className="ml-auto text-[10px] text-gray-400">
            {adjuntos.length} archivo{adjuntos.length !== 1 ? "s" : ""}
          </span>
        </div>

        <div className="p-4 space-y-4">
          {/* Upload area */}
          {data.estadoHistoria !== "Cerrada" && (
            <div className="border-2 border-dashed border-teal-300 rounded-xl p-4 bg-teal-50/40 space-y-3">
              <p className="text-xs font-bold text-teal-800">
                Subir nuevo adjunto
              </p>
              <div className="flex flex-wrap gap-3 items-end">
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] font-bold text-gray-600 uppercase">
                    Tipo de documento
                  </label>
                  <select
                    id="adjunto-tipo-select"
                    className="p-2 border rounded-lg text-xs bg-white min-w-[180px]"
                    defaultValue="otro"
                  >
                    {TIPOS_ADJUNTO.map((t) => (
                      <option key={t.valor} value={t.valor}>
                        {t.etiqueta}
                      </option>
                    ))}
                  </select>
                </div>
                <label className="cursor-pointer px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-xs font-black rounded-lg flex items-center gap-2">
                  <span>â¬† Seleccionar archivo</span>
                  <input
                    type="file"
                    className="hidden"
                    accept=".pdf,.png,.jpg,.jpeg,.tiff,.webp"
                    onChange={handleSubirAdjunto}
                  />
                </label>
              </div>
              <p className="text-[10px] text-gray-400">
                Formatos: PDF, PNG, JPG, TIFF, WebP · Máx. {MAX_MB} MB · Se
                almacena en Supabase Storage
              </p>
            </div>
          )}

          {/* Lista de adjuntos */}
          {adjuntos.length === 0 ? (
            <div className="text-center py-10 text-gray-400">
              <p className="text-3xl mb-2">ðŸ“‚</p>
              <p className="text-sm font-bold">Sin adjuntos</p>
              <p className="text-xs mt-1">
                Suba espirometrías, audiometrías, resultados de laboratorio u
                otros documentos clínicos
              </p>
            </div>
          ) : (
            <div className="divide-y divide-gray-100">
              {adjuntos.map((adj) => (
                <div
                  key={adj.id}
                  className="flex items-center justify-between gap-3 py-3 px-2 hover:bg-gray-50 rounded-lg"
                >
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <span className="text-2xl flex-shrink-0">
                      {adj.mimeType === "application/pdf" ? "ðŸ“„" : "ðŸ–¼ï¸"}
                    </span>
                    <div className="min-w-0">
                      <p className="text-xs font-bold text-gray-800 truncate">
                        {adj.nombre}
                      </p>
                      <p className="text-[10px] text-gray-400 mt-0.5">
                        {formatBytes(adj.tamano)} ·{" "}
                        {new Date(adj.fecha).toLocaleDateString("es-CO")} ·{" "}
                        {adj.subidoPor}
                      </p>
                    </div>
                  </div>
                  <div className="flex gap-2 flex-shrink-0">
                    <button
                      onClick={() => handleVerAdjunto(adj)}
                      className="px-3 py-1.5 text-[10px] font-bold text-blue-700 bg-blue-50 hover:bg-blue-100 rounded-lg"
                    >
                      ðŸ‘ Ver
                    </button>
                    {data.estadoHistoria !== "Cerrada" && (
                      <button
                        onClick={() => handleEliminarAdjunto(adj)}
                        className="px-3 py-1.5 text-[10px] font-bold text-red-600 bg-red-50 hover:bg-red-100 rounded-lg"
                      >
                        ðŸ—‘
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Nota normativa */}
          <div className="bg-amber-50 border border-amber-200 rounded-lg p-3">
            <p className="text-[10px] text-amber-800 font-bold">
              ðŸ“‹ Normativa aplicable
            </p>
            <p className="text-[10px] text-amber-700 mt-0.5">
              Los resultados de paraclínicos forman parte integral de la
              Historia Clínica Ocupacional según la Res. 1843/2025 Art. 12 y la
              Res. 1995/1999 (retención 20 años). Los archivos se almacenan en
              Supabase Storage con acceso restringido por credenciales del
              médico.
            </p>
          </div>
        </div>
      </div>
    );
  };

  // â”€â”€â”€ ROUTER â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
